{"command":"$path = Join-Path $env:USERPROFILE 'Desktop\drop.csv'
$backup = Join-Path $env:USERPROFILE ('Desktop\drop.csv.bak_' + (Get-Date -Format 'yyyyMMdd_HHmmss'))
Copy-Item -LiteralPath $path -Destination $backup -Force

$map = @{
    1 = 8310148
    2 = 8310149
    3 = 8310151
    4 = 8310153
    5 = 8310154
    6 = 8310155
    7 = 8310156
    8 = 8310157
    9 = 8310152
    10 = 8310150
}

$lines = Get-Content -LiteralPath $path
$newLines = foreach ($line in $lines) {
    if ($line -match '^(\d+),') {
        $rowId = [int]$matches[1]
        $pos = $rowId % 1000
        if ($pos -eq 0) { $pos = 1000 }
        if ($pos -ge 1 -and $pos -le 40 -and $line -match 'ItemID=83101\d{2}') {
            $idx = [int][math]::Floor(($pos - 1) / 4) + 1
            $line -replace 'ItemID=83101\d{2}', ('ItemID=' + $map[$idx])
        } else {
            $line
        }
    } else {
        $line
    }
}
Set-Content -LiteralPath $path -Value $newLines -Encoding UTF8
"backup=$backup"","timeout_ms":10000}

{"command":"$path = Join-Path $env:USERPROFILE 'Desktop\drop.csv'
$expected = @(8310148,8310149,8310151,8310153,8310154,8310155,8310156,8310157,8310152,8310150)
$bad = @()
Get-Content -LiteralPath $path | ForEach-Object {
    if ($_ -match '^(\d+),' -and $_ -match 'ItemID=(83101\d{2})') {
        $rowId = [int]$matches[1]
        $item = [int]$matches[2]
        $pos = $rowId % 1000
        if ($pos -eq 0) { $pos = 1000 }
        if ($pos -ge 1 -and $pos -le 40) {
            $idx = [int][math]::Floor(($pos - 1) / 4)
            if ($item -ne $expected[$idx]) { $bad += "row=$rowId pos=$pos item=$item expected=$($expected[$idx])" }
        }
    }
}
if ($bad.Count -eq 0) { 'mapping-ok' } else { $bad }","timeout_ms":10000}

